    if color == 'FF00FF00':
        green.add((r,c))

print('Green cells count:', len(green))

def get_neighbors(r, c):
    return [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]

adj = {cell: [n for n in get_neighbors(*cell) if n in green] for cell in green}

for cell in sorted(green):
    print(f'{cell}: degree={len(adj[cell])}, neighbors={adj[cell]}')

cells = sorted(green)
n = len(cells)
start = cells[0]

def hamiltonian_cycle():
    path = [start]
    visited = {start}

    def backtrack():
        if len(path) == n:
            return start in adj[path[-1]]
        cur = path[-1]
        for nb in adj[cur]:
            if nb not in visited:
                path.append(nb)
                visited.add(nb)
                if backtrack():
                    return True
                path.pop()
                visited.remove(nb)
        return False

    return backtrack()

result = hamiltonian_cycle()
print('Hamiltonian cycle exists:', result)
